// Generated by esquadro: do not edit. What the site's pages do in the
// browser: the account's forms, sent to the app's identity routes, sharing
// a page, and a redirect's countdown. Every page works without it but the
// forms.
(() => {
  "use strict"

  const words = () => {
    try {
      return JSON.parse(document.getElementById("site-words")?.textContent || "{}")
    } catch {
      return {}
    }
  }

  // The words of an answer's problem: a password refused says why (too
  // short or too long with its limit), an email that is not one says so,
  // else its code's, or its title.
  const problem = async (res) => {
    const w = words()
    let body = {}
    try {
      body = await res.json()
    } catch {}
    const code = body.code || ""
    const fields = Array.isArray(body.errors) ? body.errors : []
    const password = fields.find((f) => f.field === "password" || f.field === "new_password")
    if (code === "invalid_fields" && password && w["password_" + password.code]) {
      const limit = (key) => String(password.limit || w[key] || "")
      return w["password_" + password.code].replace("{min}", limit("min")).replace("{max}", limit("max"))
    }
    if (code === "invalid_fields" && fields.length === 1 && w[fields[0].field + "_" + fields[0].code]) return w[fields[0].field + "_" + fields[0].code]
    return w["error_" + code] || body.title || w.somethingWrong || "Error"
  }

  const csrf = async (identity) => {
    const res = await fetch(identity + "/session", { credentials: "same-origin" })
    if (!res.ok) return ""
    const s = await res.json()
    return s.csrf_token || ""
  }

  const say = (form, text, ok) => {
    const m = form.querySelector("[data-message]")
    if (!m) return
    m.textContent = text
    m.classList.remove("hidden")
    m.classList.toggle("text-destructive", !ok)
  }

  const send = async (form) => {
    const d = form.dataset
    if (d.confirm && !window.confirm(d.confirm)) return
    const body = Object.fromEntries(new FormData(form))
    const path = d.identity
    if (path.endsWith("/sign-in")) body.cookie = true
    if (d.redirect) body.redirect = d.redirect
    if (d.token !== undefined) body.token = d.token
    const headers = { "Content-Type": "application/json", Accept: "application/json" }
    if (d.csrf !== undefined) headers["X-CSRF-Token"] = await csrf(path.replace(/\/sign-out$/, ""))
    const button = form.querySelector("button[type=submit]")
    if (button) button.disabled = true
    try {
      const res = await fetch(path, {
        method: d.method || "POST",
        headers,
        credentials: "same-origin",
        body: d.method === "DELETE" ? undefined : JSON.stringify(body),
      })
      if (!res.ok) {
        say(form, await problem(res), false)
        return
      }
      if (d.done) {
        say(form, d.done, true)
        form.querySelectorAll("input").forEach((i) => (i.value = ""))
        return
      }
      window.location.assign(d.next || "/")
    } catch {
      say(form, words().offline || "Offline", false)
    } finally {
      if (button) button.disabled = false
    }
  }

  document.addEventListener("submit", (e) => {
    const form = e.target
    if (!(form instanceof HTMLFormElement) || form.dataset.identity === undefined) return
    e.preventDefault()
    send(form)
  })

  document.addEventListener("click", (e) => {
    const a = e.target instanceof Element ? e.target.closest("[data-share]") : null
    if (!a || !navigator.share) return
    e.preventDefault()
    navigator.share({ title: a.dataset.shareTitle, url: a.dataset.share }).catch(() => {})
  })

  // A redirect's page: its seconds counted down, its bar filled, then on to
  // where it goes, leaving no step back to it (the page's refresh does the
  // same without this).
  const countdown = (el) => {
    const wait = Number(el.dataset.countdown) || 1
    const text = el.querySelector("[data-countdown-text]")
    const bar = el.querySelector("[data-countdown-bar]")
    let passed = 0
    const tick = () => {
      if (text) text.textContent = text.dataset.countdownText.replace("{n}", String(wait - passed))
      if (bar) bar.style.width = (Math.min(passed + 1, wait) / wait) * 100 + "%"
      if (passed >= wait) {
        window.location.replace(el.dataset.to)
        return
      }
      passed++
      setTimeout(tick, 1000)
    }
    tick()
  }

  const auto = () => {
    document.querySelectorAll("form[data-auto]").forEach((f) => send(f))
    document.querySelectorAll("[data-countdown]").forEach(countdown)
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", auto)
  else auto()
})()
